  src.buffer=noiseBuf(4);src.loop=true;lp.type='lowpass';lp.frequency.value=160;lp.Q.value=.8;g.gain.value=0;
  src.connect(lp);lp.connect(g);g.connect(MASTER);src.start();VOLA.src=src;VOLA.g=g;VOLA.lp=lp;
  /* o ronco oscila de forma irregular: amplitude e filtro mudam a cada instante */
  VOLA.iv=setInterval(()=>{if(!VOLA.src)return;const t=AC.currentTime;VOLA.g.gain.setTargetAtTime(.25+.45*Math.random(),t,.3);VOLA.lp.frequency.setTargetAtTime(110+120*Math.random(),t,.3)},300);
