   s.buffer=noiseBuf(.12);hp.type='highpass';hp.frequency.value=1200+Math.random()*2000;const t=AC.currentTime;gg.gain.setValueAtTime(.35,t);gg.gain.exponentialRampToValueAtTime(.001,t+.12);
