/* módulo de pouso (Âncora-7): você desce dentro dele; para sair, chame-o (F ou Sair) e ele vem até você */
function spawnLander(){const gy=floorY(-10,0);S.lander={x:-10,z:0,y:gy-110,groundY:gy,call:false,desc:0,door:0,flame:0,landed:false,lift:false,liftT:0,climb:0}}
