 const dx=u.x-L.x,dz=u.z-L.z,d=Math.hypot(dx,dz);
 if(d<8){if(!L.arrived)msg('Âncora-7 chegou. Aperte Sair (R) para embarcar.',2600);L.arrived=true;L.flame=0;return}
