/* cadeia de áudio: mixagem -> compressor -> saída. O compressor evita estouro quando tiro, explosão,
   criatura e música tocam juntos; o ganho final continua sendo o volume do jogador. */
function audioOn(){if(AC)return AC;AC=new(window.AudioContext||window.webkitAudioContext)();MASTER=AC.createGain();MASTER.gain.value=CFG.vol/100;
