/* ---------- fundo espacial em camadas (cache) ----------
   Antes, cada quadro recriava centenas de estrelas e gradientes. Agora o campo é desenhado uma vez
   num canvas fora da tela e reutilizado; só um punhado de estrelas cintila por cima. */
const SHOOT=[];let SHOOT_NEXT=0;
function starLayer(seed,n){
 const key=seed+'|'+n+'|'+Math.round(VW)+'x'+Math.round(VH);
 let L=STAR_CACHE.get(key);if(L)return L;
 const c=document.createElement('canvas');c.width=Math.max(2,Math.round(VW));c.height=Math.max(2,Math.round(VH));
 const q=c.getContext('2d'),r=mulberry(hstr(seed)),pts=[];
 for(let i=0;i<n;i++){const x=r()*VW,y=r()*VH,s=r()*1.5+.25,a=.25+.7*r(),tint=r();
  q.fillStyle=tint<.08?'#bcd8ff':tint<.14?'#ffe2b8':tint<.18?'#d8c6ff':'#ffffff';
  q.globalAlpha=a;q.fillRect(x,y,s,s);if(i%7===0){q.globalAlpha=a*.35;q.fillRect(x-s,y-s,s*2.4,s*2.4)}
  if(pts.length<36)pts.push({x,y,s,a});}
 q.globalAlpha=1;
 L={cv:c,pts};STAR_CACHE.set(key,L);if(STAR_CACHE.size>24)STAR_CACHE.delete(STAR_CACHE.keys().next().value);return L}
function nebula(seed,alpha){
 if(!/mapbg|orbit|planet|title/.test(seed))return;
 const key=seed+'|'+Math.round(VW)+'x'+Math.round(VH);
 let c=NEB_CACHE.get(key);
 if(!c){c=document.createElement('canvas');c.width=Math.max(2,Math.round(VW/2));c.height=Math.max(2,Math.round(VH/2));const q=c.getContext('2d'),r=mulberry(hstr('neb|'+seed));
  const P=[['#2a6cff','#8b3dff','#12d6c8'],['#ff4d8d','#6a2bff','#ffb04d'],['#1fd6ff','#2a4dff','#7affb0'],['#ff7a3d','#b02a7a','#5a2aff']][hstr(seed)%4];
  q.globalCompositeOperation='lighter';
  for(let i=0;i<14;i++){const x=r()*c.width,y=r()*c.height,rad=(.12+r()*.38)*Math.min(c.width,c.height),col=P[Math.floor(r()*P.length)];
   const gr=q.createRadialGradient(x,y,0,x,y,rad);gr.addColorStop(0,col+'55');gr.addColorStop(.45,col+'1c');gr.addColorStop(1,col+'00');q.fillStyle=gr;q.beginPath();q.arc(x,y,rad,0,6.283);q.fill()}
  /* poeira escura recorta o brilho e dá profundidade */
  q.globalCompositeOperation='source-over';
  for(let i=0;i<7;i++){const x=r()*c.width,y=r()*c.height,rad=(.1+r()*.3)*Math.min(c.width,c.height);
   const gr=q.createRadialGradient(x,y,0,x,y,rad);gr.addColorStop(0,'rgba(0,3,10,.30)');gr.addColorStop(1,'rgba(0,3,10,0)');q.fillStyle=gr;q.beginPath();q.arc(x,y,rad,0,6.283);q.fill()}
  NEB_CACHE.set(key,c);if(NEB_CACHE.size>6)NEB_CACHE.delete(NEB_CACHE.keys().next().value)}
 g.save();g.globalAlpha=alpha==null?.55:alpha;g.drawImage(c,0,0,VW,VH);g.restore()}
function stars(seed,n,k){
 nebula(seed);
 const L=starLayer(seed,n);g.drawImage(L.cv,0,0,VW,VH);
 /* cintilação: só 36 estrelas, com brilho suave e defasado */
 for(const q of L.pts){const a=q.a*(.55+.45*Math.sin(S.t*1.9+q.x*.07+q.y*.03));g.globalAlpha=clamp(a,0,1);g.fillStyle='#fff';g.fillRect(q.x,q.y,q.s,q.s)}
 g.globalAlpha=1;
 /* estrela cadente ocasional: riscos curtos que atravessam o céu */
 if(S.t>SHOOT_NEXT){SHOOT_NEXT=S.t+9+Math.random()*18;if(SHOOT.length<2)SHOOT.push({x:VW*(.1+Math.random()*.8),y:VH*(.05+Math.random()*.35),vx:-(160+Math.random()*220),vy:80+Math.random()*90,t:0,life:.7+Math.random()*.5})}
 for(let i=SHOOT.length-1;i>=0;i--){const s=SHOOT[i];s.t+=1/60;const p=s.t/s.life;if(p>=1){SHOOT.splice(i,1);continue}
  const x=s.x+s.vx*s.t,y=s.y+s.vy*s.t,l=26*(1-p),a=Math.sin(p*Math.PI)*.85;
  g.strokeStyle=`rgba(210,245,255,${a.toFixed(3)})`;g.lineWidth=1.4;g.beginPath();g.moveTo(x,y);g.lineTo(x-l,y-l*.55);g.stroke()}}

