/* ---------- controle (gamepad) ----------
   Converte analógicos e botões em teclas virtuais. O teclado continua funcionando junto:
   o Set original é preservado e a consulta keys.has() também considera as teclas do controle. */
const PAD_KEYS=new Set();
{const hasKey=keys.has.bind(keys);keys.has=k=>hasKey(k)||PAD_KEYS.has(k)}
let PAD_PREV=[];
