 const list=navigator.getGamepads?navigator.getGamepads():[];let gp=null;
 for(const p of list){if(p&&p.connected){gp=p;break}}
 PAD_KEYS.clear();
 if(!gp){PAD_PREV=[];return}
 const b=gp.buttons||[],ax=gp.axes||[],press=i=>!!(b[i]&&b[i].pressed),dz=.3;
 const edge=(i,key)=>{if(press(i)&&!PAD_PREV[i])dispatchEvent(new KeyboardEvent('keydown',{key,bubbles:true}));else if(!press(i)&&PAD_PREV[i])dispatchEvent(new KeyboardEvent('keyup',{key,bubbles:true}))};
 /* Start pausa/retoma mesmo com o menu aberto */
 edge(9,'Escape');
 if(!hudTitleUp()&&!S.paused){
  const lx=ax[0]||0,ly=ax[1]||0,rx=ax[2]||0,ry=ax[3]||0;
  if(lx<-dz)PAD_KEYS.add('a');if(lx>dz)PAD_KEYS.add('d');
  if(ly<-dz)PAD_KEYS.add('w');if(ly>dz)PAD_KEYS.add('s');
  if(rx<-dz)PAD_KEYS.add('arrowleft');if(rx>dz)PAD_KEYS.add('arrowright');
  if(ry<-dz)PAD_KEYS.add('arrowup');if(ry>dz)PAD_KEYS.add('arrowdown');
  if(press(0)||press(7))PAD_KEYS.add(' '); /* A / gatilho direito: atirar, pular, subir */
  if(press(6)||press(4))PAD_KEYS.add('shift'); /* LT / LB: turbo */
  if(press(12))PAD_KEYS.add('w');if(press(13))PAD_KEYS.add('s');if(press(14))PAD_KEYS.add('a');if(press(15))PAD_KEYS.add('d');
  edge(1,'f'); /* B: interagir */
